class Solution { public:
    string smallestNumber(string pattern) {
        string ans;stack<char> st;
        for(int i=0;i<=(int)pattern.size();++i){
            st.push(char('1'+i));
            if(i==(int)pattern.size()||pattern[i]=='I')while(!st.empty()){ans+=st.top();st.pop();}
        }
        return ans;
    }
};
